// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address sender) public {
        amount = bound(amount, 1, 1 ether);
        vm.assume(sender != address(0));

        vm.deal(sender, amount);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: amount}("");
        if (address(c).balance > 0) {
            assertTrue(c.depositsCount() >= 1);
        } else {
            assertTrue(c.depositsCount() >= 0);
        }
    }
}
